let libraryFavoritesOnly=false;
function libraryTypeLabel(t){return {culture:'Culture',disease:'Maladie',pest:'Ravageur',deficiency:'Carence'}[t]||t}
function libraryFindCrop(name=''){const n=normCrop(name);return LIBRARY_ITEMS.find(x=>x.type==='culture'&&(normCrop(x.name)===n||normCrop(x.name).includes(n)||n.includes(normCrop(x.name))))}
function libraryCalendar(item){const key=seedKey(item.name),cal=key&&SEED_CALENDAR[key],off=climateOffset();if(!cal)return '';return `<div class="seed-calendar library-calendar"><span><b>Semis sous abri</b>${rangeText(cal.indoor,off)}</span><span><b>Pleine terre</b>${rangeText(cal.outdoor,off)}</span><span><b>Plantation</b>${rangeText(cal.plant,off)}</span><span><b>Récolte</b>${rangeText(cal.harvest,off)}</span></div>`}
function renderLibrary(){
 const box=$('#libraryCards');if(!box)return;
 const q=normCrop($('#librarySearch')?.value||''),cat=$('#libraryCategory')?.value||'',fav=state.settings.libraryFavorites||[];
 let arr=LIBRARY_ITEMS.filter(x=>(!cat||x.type===cat)&&(!q||normCrop(Object.values(x).join(' ')).includes(q))&&(!libraryFavoritesOnly||fav.includes(x.id)));
 $('#librarySummary').innerHTML=[[LIBRARY_ITEMS.filter(x=>x.type==='culture').length,'fiches cultures','🥕'],[LIBRARY_ITEMS.filter(x=>x.type==='disease').length,'maladies','🦠'],[LIBRARY_ITEMS.filter(x=>x.type==='pest').length,'ravageurs','🐛'],[fav.length,'favoris','⭐']].map(x=>`<div class="stat"><span>${x[2]}</span><b>${x[0]}</b><span>${x[1]}</span></div>`).join('');
 box.innerHTML=arr.length?arr.map(x=>`<article class="library-card" onclick="openLibraryItem('${x.id}')"><button class="favorite-btn ${fav.includes(x.id)?'active':''}" onclick="event.stopPropagation();toggleLibraryFavorite('${x.id}')" aria-label="Favori">${fav.includes(x.id)?'★':'☆'}</button><div class="library-icon">${x.icon}</div><span class="pill">${libraryTypeLabel(x.type)}</span><h3>${esc(x.name)}</h3><p>${esc(x.type==='culture'?x.tip:x.symptoms)}</p><button class="small">Ouvrir la fiche</button></article>`).join(''):'<div class="card empty">Aucune fiche ne correspond à la recherche.</div>';
}
window.toggleLibraryFavorite=id=>{const f=state.settings.libraryFavorites||[];state.settings.libraryFavorites=f.includes(id)?f.filter(x=>x!==id):[...f,id];save()};
window.openLibraryItem=id=>{const x=LIBRARY_ITEMS.find(i=>i.id===id);if(!x)return;$('#libraryDialogTitle').textContent=`${x.icon} ${x.name}`;const fav=(state.settings.libraryFavorites||[]).includes(x.id);let body='';if(x.type==='culture'){body=`<div class="detail-badges"><span>🌿 ${esc(x.family)}</span><span>☀️ ${esc(x.sun)}</span><span>💧 ${esc(x.water)}</span><span>📏 ${esc(x.spacing)}</span></div>${libraryCalendar(x)}<div class="detail-grid"><section><h4>🌱 Fertilisation</h4><p>${esc(x.fertilizer)}</p></section><section><h4>🤝 Bons voisins</h4><p>${esc(x.good)}</p></section><section><h4>⚠️ À éviter</h4><p>${esc(x.bad)}</p></section><section><h4>🦠 Risques fréquents</h4><p>${esc(x.risks)}</p></section></div><div class="tip-box"><b>💡 Conseil</b><p>${esc(x.tip)}</p></div>`}else{body=`<div class="detail-grid"><section><h4>🔍 Symptômes / dégâts</h4><p>${esc(x.symptoms)}</p></section><section><h4>❓ Cause ou contexte</h4><p>${esc(x.cause)}</p></section><section><h4>🛡️ Prévention et action</h4><p>${esc(x.action)}</p></section><section><h4>🌱 Cultures concernées</h4><p>${esc(x.targets)}</p></section></div>`}$('#libraryDialogBody').innerHTML=`<button class="secondary favorite-detail" onclick="toggleLibraryFavorite('${x.id}')">${fav?'★ Retirer des favoris':'☆ Ajouter aux favoris'}</button>${body}<p class="library-warning">Conseils généraux à adapter au climat, au sol et aux indications des produits utilisés.</p>`;$('#libraryDialog').showModal()};
window.openLibraryForCrop=name=>{const x=libraryFindCrop(name);switchView('library');if(x)openLibraryItem(x.id);else{$('#librarySearch').value=name;renderLibrary();alert('Aucune fiche exacte trouvée. La bibliothèque affiche les résultats proches.')}};
$('#librarySearch')?.addEventListener('input',()=>{libraryFavoritesOnly=false;renderLibrary()});
$('#libraryCategory')?.addEventListener('change',()=>{libraryFavoritesOnly=false;renderLibrary()});
$('#showFavorites')?.addEventListener('click',()=>{libraryFavoritesOnly=!libraryFavoritesOnly;$('#showFavorites').textContent=libraryFavoritesOnly?'📚 Voir toutes les fiches':'⭐ Mes favoris';renderLibrary()});

renderAll();

// V3.6.1 — garde l’onglet actif entièrement visible dans le bandeau mobile.
document.addEventListener('click', (event) => {
  const tab = event.target.closest('.tab');
  if (!tab) return;
  window.setTimeout(() => tab.scrollIntoView({behavior:'smooth', block:'nearest', inline:'center'}), 20);
});
